Here is the final script that automates the whole process using `agent-browser`. Since Windows PowerShell quoting can sometimes be tricky for complex inline JavaScript, I've created a Node.js wrapper that handles the CLI calls properly.

You can run this script using `node scrape.js`:

```javascript
// scrape.js
const { execSync } = require('child_process');
const fs = require('fs');

function runCommand(command) {
    console.warn(`Running: ${command}`);
    try {
        return execSync(command, { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'], shell: 'powershell.exe' });
    } catch (e) {
        console.warn(`Command failed but continuing: ${e.message}`);
        return null;
    }
}

function runEval(evalCmd) {
    // Avoid escaping issues by running the JavaScript completely safely
    const cmd = `agent-browser eval "${evalCmd.replace(/"/g, '\\"')}" --json`;
    try {
        const output = execSync(cmd, { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'], shell: 'powershell.exe' });
        const jsonLine = output.trim().split('\n').find(line => line.includes('"success":true'));
        if (jsonLine) {
            return JSON.parse(jsonLine).data.result;
        }
        return [];
    } catch (e) {
        console.error("Error parsing eval output:", e);
        return [];
    }
}

async function scrape() {
    console.log("Starting scraping process...");

    // 1. Open the page
    runCommand(`agent-browser open https://inmobiliariaiparralde.com/`);
    runCommand(`agent-browser wait --load networkidle`);

    // 2. Accept cookies if not accepted yet
    runCommand(`agent-browser eval "Array.from(document.querySelectorAll('a')).find(el => el.innerText.includes('ACEPTAR COOKIES'))?.click();"`);

    // 3. Search: Comprar/Alquilar, Piso, Hendaye
    runCommand(`agent-browser eval "Array.from(document.querySelectorAll('a')).find(el => el.innerText === 'Alquilar')?.click();"`);
    runCommand(`agent-browser eval "
        const ddInm = Array.from(document.querySelectorAll('button')).find(b => b.innerText.includes('Tipo de Inmueble')); if (ddInm) ddInm.click();
        const optPiso = Array.from(document.querySelectorAll('a, span, li')).find(e => e.innerText === 'Piso'); if (optPiso) optPiso.click();

        const ddDonde = Array.from(document.querySelectorAll('button')).find(b => b.innerText.includes('¿Donde?')); if (ddDonde) ddDonde.click();
        const optHendaye = Array.from(document.querySelectorAll('a, span, li')).find(e => e.innerText === 'Hendaye'); if (optHendaye) optHendaye.click();

        const submit = Array.from(document.querySelectorAll('button')).find(b => b.querySelector('.fa-search')); if (submit) submit.click();
    "`.replace(/\n/g, ' '));

    // Wait for the results load
    runCommand(`agent-browser wait --load networkidle`);

    let allResults = [];
    const extractEval = `
        Array.from(document.querySelectorAll('div.col-sm-9 h3')).map(h3 => {
            const grandpa = h3.parentElement?.parentElement?.parentElement;
            const fullText = grandpa?.innerText;
            const lines = fullText ? fullText.split(/\\r?\\n/).map(l => l.trim()).filter(Boolean) : [];
            const price = lines.find(l => l.match(/€/)) || lines.find(l => l.toLowerCase().includes('precio consultar')) || 'N/A';
            const loc = lines.find(l => l.match(/\\d{5}/)) || 'N/A';
            const url = h3.parentElement?.href;
            return {
                title: h3.innerText.trim(),
                price: price,
                location: loc,
                url: url,
                id: url ? url.split('/').pop() : null,
                timestamp: new Date().toISOString()
            };
        })
    `.replace(/\n/g, ' ');

    let currentPage = 1;
    let hasNextPage = true;

    while (hasNextPage && currentPage <= 3) { // Pagination (usually 2-3 pages max)
        console.log(`Extracting page ${currentPage}...`);
        const pageResults = runEval(extractEval);
        allResults = allResults.concat(pageResults);

        // Try to go to next page
        const nextPageNum = currentPage + 1;
        const pageClicked = runEval(`
            const nextLink = Array.from(document.querySelectorAll('a')).find(a => a.innerText === '${nextPageNum}');
            if (nextLink) {
                nextLink.click();
                true;
            } else {
                false;
            }
        `.replace(/\n/g, ' '));

        if (pageClicked === true) {
            runCommand(`agent-browser wait --load networkidle`);
            currentPage++;
        } else {
            hasNextPage = false;
        }
    }

    // Deduplicate results by id 
    const uniqueResultsMap = new Map();
    allResults.forEach(r => uniqueResultsMap.set(r.id, r));
    const uniqueResults = Array.from(uniqueResultsMap.values());

    // Save final output
    const jsonOutput = JSON.stringify(uniqueResults, null, 2);
    fs.writeFileSync('results.json', jsonOutput);
    console.log(`\nSaved ${uniqueResults.length} records to results.json`);

    runCommand(`agent-browser close`);
}

scrape();
